static bool validate_utf8_scalar(const unsigned char *bytes, size_t length,
                                 size_t index, unsigned int carry) {
  unsigned int pending = 0;
  while (carry & 1u) {
    ++pending;
    carry >>= 1;
  }
  if (carry != 0) {
    return false;
  }

  while (index < length) {
    unsigned char first = bytes[index];
    if (pending != 0) {
      if ((first & 0xC0) != 0x80) {
        return false;
      }
      --pending;
      ++index;
      continue;
    }

    if (first < 0x80) {
      ++index;
    } else if (first <= 0xDF) {
      if (first < 0xC2 || length - index < 2 ||
          (bytes[index + 1] & 0xC0) != 0x80) {
        return false;
      }
      index += 2;
    } else if (first <= 0xEF) {
      if (length - index < 3) {
        return false;
      }
      unsigned char second = bytes[index + 1];
      if ((second & 0xC0) != 0x80 ||
          (first == 0xE0 && second < 0xA0) ||
          (first == 0xED && second > 0x9F) ||
          (bytes[index + 2] & 0xC0) != 0x80) {
        return false;
      }
      index += 3;
    } else {
      if (first > 0xF4 || length - index < 4) {
        return false;
      }
      unsigned char second = bytes[index + 1];
      if ((second & 0xC0) != 0x80 ||
          (first == 0xF0 && second < 0x90) ||
          (first == 0xF4 && second > 0x8F) ||
          (bytes[index + 2] & 0xC0) != 0x80 ||
          (bytes[index + 3] & 0xC0) != 0x80) {
        return false;
      }
      index += 4;
    }
  }
  return pending == 0;
}

