static bool validate_utf8(const char *buffer, size_t length) {
  const unsigned char *bytes = (const unsigned char *)buffer;
#if UTF8_HAVE_X86_SIMD
  if (length >= 64 && __builtin_cpu_supports("avx2")) {
    return validate_utf8_avx2(bytes, length);
  }
  if (length >= 16 && __builtin_cpu_supports("sse2")) {
    return validate_utf8_sse2(bytes, length);
  }
#endif
  return validate_utf8_scalar(bytes, length, 0, 0);
}

