  unsigned int remaining = 0;
  unsigned char next_min = 0x80u;
  unsigned char next_max = 0xBFu;

  while (index < length) {
    if (remaining == 0) {
      while (index < length && bytes[index] < 0x80u) {
        ++index;
      }
      if (index == length) {
        return true;
      }

      unsigned char byte = bytes[index++];
      if (byte >= 0xC2u && byte <= 0xDFu) {
        remaining = 1;
        next_min = 0x80u;
        next_max = 0xBFu;
      } else if (byte == 0xE0u) {
        remaining = 2;
        next_min = 0xA0u;
        next_max = 0xBFu;
      } else if (byte == 0xEDu) {
        remaining = 2;
        next_min = 0x80u;
        next_max = 0x9Fu;
      } else if (byte >= 0xE1u && byte <= 0xEFu) {
        remaining = 2;
        next_min = 0x80u;
        next_max = 0xBFu;
      } else if (byte == 0xF0u) {
        remaining = 3;
        next_min = 0x90u;
        next_max = 0xBFu;
      } else if (byte >= 0xF1u && byte <= 0xF3u) {
        remaining = 3;
        next_min = 0x80u;
        next_max = 0xBFu;
      } else if (byte == 0xF4u) {
        remaining = 3;
        next_min = 0x80u;
        next_max = 0x8Fu;
      } else {
        return false;
      }
    } else {
      unsigned char byte = bytes[index++];
      if (byte < next_min || byte > next_max) {
        return false;
      }
      --remaining;
      next_min = 0x80u;
      next_max = 0xBFu;
    }
  }

  return remaining == 0;
}

